28	/// All access to this connection stays on the main actor. The core owns SQL,
29	/// migrations and revisions; views only submit explicit editing requests.
30	@MainActor
31	final class LaboratoryModel: ObservableObject {
32	    @Published private(set) var store: LabStore?
33	    @Published private(set) var catalog: LabCatalogStore?
34	    @Published private(set) var generation = 0
35	    @Published private(set) var startupError: String?
36	
37	    init() { open() }
38	
39	    func open() {
40	        do {
41	            let root = try FileManager.default.url(for: .applicationSupportDirectory,
42	                in: .userDomainMask, appropriateFor: nil, create: true)
43	                .appendingPathComponent("Almanac", isDirectory: true)
44	            try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
45	            let db = try Database(path: root.appendingPathComponent("almanac.sqlite").path)
46	            try MigrationRunner(migrations: AlmanacMigrations.all).migrate(db)
47	            let catalog = LabCatalogStore(db: db)
48	            try LabCatalogSeed.seed(into: catalog)
49	            self.catalog = catalog
50	            store = LabStore(db: db)
51	            startupError = nil
52	        } catch {
53	            // Never reset or replace a database after a failed migration/open.
54	            startupError = String(describing: error)
55	        }
56	    }
57	
58	    func changed() { generation += 1 }
59	}
