83	/// Text and precision remain explicit; no DatePicker invents a missing date.
84	@MainActor
85	struct PartialDateFields: View {
86	    @Binding var text: String
87	    @Binding var precision: TimePrecision
88	    var body: some View {
89	        Picker("Precision", selection: $precision) {
90	            ForEach(TimePrecision.allCases, id: \.self) { Text(readable($0.rawValue)).tag($0) }
91	        }
92	        if precision == .unknown {
93	            Text("Date unknown").foregroundStyle(.secondary)
94	        } else {
95	            TextField(example, text: $text)
96	                .textInputAutocapitalization(.never).autocorrectionDisabled()
97	            Text("Enter only what is known. Add Z or +03:00 to a time only if the source states an offset.")
98	                .font(.caption).foregroundStyle(.secondary)
99	        }
100	    }
101	    private var example: String {
102	        switch precision {
103	        case .unknown: return "Unknown"
104	        case .year: return "2026"
105	        case .month: return "2026-09"
106	        case .day: return "2026-09-08"
107	        case .hour: return "2026-09-08T10"
108	        case .minute: return "2026-09-08T10:30"
109	        case .instant: return "2026-09-08T10:30:00+03:00"
110	        }
111	    }
112	}
113	
114	func editedDate(text: String, precision: TimePrecision, original: PartialDateTime = .unknown) throws -> PartialDateTime {
115	    if precision == .unknown { return .unknown }
116	    if text == original.text && precision == original.precision { return original }
117	    guard let date = PartialDateTime(storedText: text, precision: precision, zone: original.zone), date.span != nil else {
118	        throw EditorFailure(message: "Enter a valid date matching the selected precision, or choose Unknown.")
119	    }
120	    return date
121	}
