18	/// Structured value and source transcription are deliberately separate. A
19	/// corrected numeric value must not be hidden by an older sourceValueText.
20	@MainActor
21	struct ContentDetails: View {
22	    let content: LabRevisionContent
23	    var body: some View {
24	        VStack(alignment: .leading, spacing: 5) {
25	            Text(value).font(.title3.monospacedDigit()).foregroundStyle(.primary)
26	            Text("Original unit: \(content.unitText ?? "Not stated")")
27	            Text("Reference: \(content.rangeText ?? "Not stated")")
28	            if content.rangeLow != nil || content.rangeHigh != nil {
29	                Text("Bounds: \(content.rangeLow.map { String($0) } ?? "Not stated") – \(content.rangeHigh.map { String($0) } ?? "Not stated")")
30	            }
31	            if let unit = content.rangeUnitText { Text("Reference unit: \(unit)") }
32	            if let name = content.sourceAnalyteText { Text("Original test: \(name)") }
33	            if let source = content.sourceValueText { Text("Original result: \(source)") }
34	            if let flag = content.flagText { Text("Reported flag: \(flag)") }
35	            Text("Derivation: \(readable(content.derivation.rawValue))")
36	        }.font(.caption).foregroundStyle(.secondary).textSelection(.enabled)
37	    }
38	    private var value: String {
39	        let raw: String
40	        switch content.valueType {
41	        case .quantitative, .semiQuantitative:
42	            raw = content.numericValue.map { String($0) } ?? "No structured value"
43	        case .qualitativeCoded, .ordinal: raw = content.codedValue ?? "No structured value"
44	        case .text: raw = content.textValue ?? "No structured value"
45	        case .ratio:
46	            raw = "\(content.ratioNumerator.map { String($0) } ?? "?"):\(content.ratioDenominator.map { String($0) } ?? "?")"
47	        case .titer:
48	            raw = "\(content.titerNumerator.map { String($0) } ?? "?"):\(content.titerDenominator.map { String($0) } ?? "?")"
49	        case .absent: raw = "Missing: \(readable((content.missingReason ?? .unknown).rawValue))"
50	        }
51	        return [content.comparator.symbol, raw, content.unitText].compactMap { $0 }.joined(separator: " ")
52	    }
53	}
