140	struct ReportConflictView: View {
141	    @ObservedObject var model: LaboratoryModel
142	    let reportID: String
143	    @State private var proposals: [LabReportRevision] = []
144	    @State private var current: LabReportSummary?
145	    @State private var reason = ""
146	    @State private var error: String?
147	    var body: some View {
148	        List {
149	            Section("Current report") {
150	                Text(current?.laboratoryNameText ?? "Laboratory unknown")
151	                Text(dateLabel(current?.reportedAt ?? .unknown))
152	            }
153	            Section("Resolution") {
154	                TextField("Reason for your decision", text: $reason, axis: .vertical)
155	                Text("Accept replaces the report metadata with the incoming version. Existing results remain attached.")
156	                    .font(.caption).foregroundStyle(.secondary)
157	            }
158	            ForEach(proposals, id: \.id) { proposal in
159	                Section("Incoming version") {
160	                    Text(proposal.laboratoryNameText ?? "Laboratory unknown")
161	                    Text(proposal.reportedAtText ?? "Date unknown")
162	                    if let header = proposal.headerText { Text(header) }
163	                    Text("Source ordering: \(ordering(proposal.sourceOrdering))")
164	                    Text("Received: \(proposal.supersededAt)")
165	                    Button("Accept incoming version") { resolve(proposal, accept: true) }
166	                    Button("Reject incoming version", role: .destructive) { resolve(proposal, accept: false) }
167	                }
168	            }
169	            if proposals.isEmpty { Text("No unresolved conflicts").foregroundStyle(.secondary) }
170	        }
171	        .navigationTitle("Report review").navigationBarTitleDisplayMode(.inline)
172	        .task { reload() }.editorError($error)
173	    }
174	    private func ordering(_ value: SourceOrdering) -> String {
175	        switch value {
176	        case .unavailable: return "Not stated"
177	        case .sequence(let n): return "Version \(n)"
178	        case .issuedAt(let text): return text
179	        }
180	    }
181	    private func reload() {
182	        do {
183	            proposals = try model.store?.reportRevisions(of: reportID).filter { $0.kind == "conflict" } ?? []
184	            current = try model.store?.report(id: reportID)
185	        } catch { self.error = String(describing: error) }
186	    }
187	    private func resolve(_ proposal: LabReportRevision, accept: Bool) {
188	        do {
189	            guard let store = model.store else { throw EditorFailure(message: "The database is unavailable.") }
190	            try store.resolveReportConflict(id: proposal.id, accept: accept, actor: "user", reason: reason)
191	            reason = ""; model.changed(); reload()
192	        } catch { self.error = String(describing: error) }
193	    }
194	}
