53	struct ReportEditor: View {
54	    @ObservedObject var model: LaboratoryModel
55	    let report: LabReportSummary?
56	    @Environment(\.dismiss) private var dismiss
57	    @State private var name: String
58	    @State private var date: String
59	    @State private var precision: TimePrecision
60	    @State private var reason = ""
61	    @State private var error: String?
62	
63	    init(model: LaboratoryModel, report: LabReportSummary?) {
64	        self.model = model; self.report = report
65	        _name = State(initialValue: report?.laboratoryNameText ?? "")
66	        _date = State(initialValue: report?.reportedAt.text ?? "")
67	        _precision = State(initialValue: report?.reportedAt.precision ?? .unknown)
68	    }
69	    var body: some View {
70	        NavigationStack {
71	            Form {
72	                Section("Laboratory") { TextField("Name, if known", text: $name) }
73	                Section("Report date") { PartialDateFields(text: $date, precision: $precision) }
74	                if report != nil {
75	                    Section("Correction") { TextField("Reason for this change", text: $reason, axis: .vertical) }
76	                }
77	            }
78	            .navigationTitle(report == nil ? "New report" : "Edit report")
79	            .navigationBarTitleDisplayMode(.inline)
80	            .toolbar {
81	                ToolbarItem(placement: .cancellationAction) { Button("Cancel") { dismiss() } }
82	                ToolbarItem(placement: .confirmationAction) { Button("Save", action: save) }
83	            }
84	            .editorError($error)
85	        }
86	    }
87	    private func save() {
88	        do {
89	            guard let store = model.store else { throw EditorFailure(message: "The database is unavailable.") }
90	            let value = try editedDate(text: date, precision: precision, original: report?.reportedAt ?? .unknown)
91	            if let report {
92	                guard !reason.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
93	                    throw EditorFailure(message: "Enter a reason for the correction.")
94	                }
95	                var edit = LabReportEdit()
96	                edit.laboratoryNameText = name.isEmpty ? .clear : .set(name)
97	                edit.reportedAt = .set(value)
98	                edit.reasonText = reason
99	                _ = try store.updateReport(id: report.id, edit)
100	            } else {
101	                var draft = LabReportDraft()
102	                draft.laboratoryNameText = optionalText(name); draft.reportedAt = value
103	                _ = try store.saveReport(draft)
104	            }
105	            model.changed(); dismiss()
106	        } catch { self.error = String(describing: error) }
107	    }
108	}
