158	            if let report { ReportEditor(model: model, report: report) }
159	        }
160	        .sheet(isPresented: Binding(get: { editingResult != nil }, set: { if !$0 { editingResult = nil } })) {
161	            if let result = editingResult { ResultEditor(model: model, reportID: reportID, result: result) }
162	        }
163	        .task { reload() }
164	        .onChange(of: model.generation) { _, _ in reload() }
165	        .editorError($error)
166	    }
167	    private func reload() {
168	        do {
169	            report = try model.store?.report(id: reportID)
170	            results = try model.store?.currentResults(inReport: reportID) ?? []
171	        } catch { self.error = String(describing: error) }
172	    }
173	}
