5	struct ResultEditor: View {
6	    @ObservedObject var model: LaboratoryModel
7	    let reportID: String
8	    let result: LabResultView?
9	    @Environment(\.dismiss) private var dismiss
10	    @State private var content: LabRevisionContent
11	    @State private var analyteID: String?
12	    @State private var testName: String
13	    @State private var query = ""
14	    @State private var suggestions: [CatalogSuggestion] = []
15	    @State private var number: String
16	    @State private var numerator: String
17	    @State private var denominator: String
18	    @State private var low: String
19	    @State private var high: String
20	    @State private var specimen: SpecimenKind
21	    @State private var specimenText: String
22	    @State private var date: String
23	    @State private var precision: TimePrecision
24	    @State private var reason = ""
25	    @State private var error: String?
26	
27	    init(model: LaboratoryModel, reportID: String, result: LabResultView?) {
28	        self.model = model; self.reportID = reportID; self.result = result
29	        var c = result?.content ?? LabRevisionContent()
30	        if result == nil { c.valueType = .quantitative }
31	        _content = State(initialValue: c)
