172	    private func save() {
173	        do {
174	            guard let store = model.store else { throw EditorFailure(message: "The database is unavailable.") }
175	            guard analyteID != nil || !(content.sourceAnalyteText ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
176	                throw EditorFailure(message: "Select a test or enter its original name.")
177	            }
178	            if result != nil && reason.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
179	                throw EditorFailure(message: "Enter a reason for this correction.")
180	            }
181	            let collected = try editedDate(text: date, precision: precision, original: result?.collectedAt ?? .unknown)
182	            var saved = content
183	            // Clear obsolete structured slots only when changing the type.
184	            // The prior revision and original text remain evidence.
185	            if result?.content.valueType != saved.valueType {
186	                saved.numericValue = nil; saved.codedValue = nil; saved.textValue = nil
187	                saved.ratioNumerator = nil; saved.ratioDenominator = nil
188	                saved.titerNumerator = nil; saved.titerDenominator = nil
189	            }
190	            saved.missingReason = saved.valueType == .absent ? (content.missingReason ?? .unknown) : nil
191	            switch saved.valueType {
192	            case .quantitative, .semiQuantitative:
193	                saved.numericValue = try decimal(number, field: "the value", required: true)
194	            case .qualitativeCoded, .ordinal:
195	                guard let value = content.codedValue, !value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
196	                    throw EditorFailure(message: "Enter the reported result.")
197	                }
198	                saved.codedValue = value
199	            case .text:
200	                guard let value = content.textValue, !value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
201	                    throw EditorFailure(message: "Enter the descriptive result.")
202	                }
203	                saved.textValue = value
204	            case .ratio:
205	                saved.ratioNumerator = try decimal(numerator, field: "numerator", required: true)
206	                saved.ratioDenominator = try decimal(denominator, field: "denominator", required: true)
207	                guard saved.ratioDenominator != 0 else { throw EditorFailure(message: "The denominator cannot be zero.") }
208	            case .titer:
209	                guard let n = Int(numerator), let d = Int(denominator), n > 0, d > 0 else {
210	                    throw EditorFailure(message: "A titer needs two positive whole numbers, such as 1 and 160.")
211	                }
212	                saved.titerNumerator = n; saved.titerDenominator = d
213	            case .absent: break
214	            }
215	            saved.rangeLow = try decimal(low, field: "lower reference bound")
216	            saved.rangeHigh = try decimal(high, field: "upper reference bound")
217	            saved.actor = "user"
218	            saved.contentOrigin = result == nil ? .userTranscription : .userCorrection
219	            saved.reasonText = result == nil ? nil : reason
220	            if let result {
221	                var edit = LabObservationMetadataEdit()
222	                if analyteID != result.catalogAnalyteID { edit.catalogAnalyteID = analyteID.map(FieldEdit.set) ?? .clear }
223	                edit.specimenKind = .set(specimen)
224	                edit.specimenText = specimenText.isEmpty ? .clear : .set(specimenText)
225	                edit.collectedAt = .set(collected); edit.reasonText = reason
226	                try store.saveManualEdit(id: result.observationID, content: saved, metadata: edit)
227	            } else {
228	                var draft = LabObservationDraft()
229	                draft.reportID = reportID; draft.catalogAnalyteID = analyteID
230	                if analyteID != nil { draft.matchOrigin = "user"; draft.matchConfidence = "user_assigned" }
231	                draft.collectedAt = collected; draft.specimenKind = specimen
232	                draft.specimenText = optionalText(specimenText)
233	                _ = try store.record(draft, content: saved)
234	            }
235	            model.changed(); dismiss()
236	        } catch { self.error = String(describing: error) }
237	    }
