3	/// The seam where HealthKit will sit.
4	///
5	/// HealthKit does not exist on Linux, so it cannot be imported by this target
6	/// at all. That constraint is useful rather than annoying: it forces the sync
7	/// algorithm to be written against a protocol and tested against a fake, and
8	/// keeps `HKHealthStore` confined to one iOS-only file in the app target.
9	///
10	/// The concrete `HealthKitProvider` belongs in the iOS target and is the only
11	/// place `import HealthKit` may appear.
12	public protocol HealthProvider: Sendable {
13	    func requestAuthorisation(for domains: [HealthDomain]) async throws
14	    /// Returns samples changed since `anchor`, plus the anchor to store next.
15	    func changes(in domain: HealthDomain, since anchor: [UInt8]?) async throws -> HealthChangeSet
16	}
17	
18	/// Domains Almanac syncs. Names are Almanac's, not HealthKit's — the mapping
19	/// to HKQuantityType/HKCategoryType lives in the iOS adapter, per the spec's
20	/// HealthKit map (which is not available here and must not be guessed).
21	public enum HealthDomain: String, Codable, Sendable, CaseIterable, Hashable {
22	    case sleep, workouts, activeEnergy, restingEnergy, steps, heartRate, hrv, bodyMass
23	}
24	
25	public struct HealthSample: Sendable, Hashable {
26	    public let externalID: String
27	    public let domain: HealthDomain
28	    public let start: Date
29	    public let end: Date
30	    public let value: Double?
31	    public let unit: String?
32	    public let sourceName: String?
33	
34	    public init(externalID: String, domain: HealthDomain, start: Date, end: Date,
35	                value: Double?, unit: String?, sourceName: String? = nil) {
36	        self.externalID = externalID
37	        self.domain = domain
38	        self.start = start
39	        self.end = end
40	        self.value = value
41	        self.unit = unit
42	        self.sourceName = sourceName
43	    }
44	}
45	
46	public struct HealthChangeSet: Sendable {
47	    public let added: [HealthSample]
48	    public let deletedExternalIDs: [String]
49	    public let nextAnchor: [UInt8]?
50	
51	    public init(added: [HealthSample], deletedExternalIDs: [String], nextAnchor: [UInt8]?) {
52	        self.added = added
53	        self.deletedExternalIDs = deletedExternalIDs
54	        self.nextAnchor = nextAnchor
55	    }
56	}
