63	/// In-memory provider used by tests and by any non-iOS host.
64	public final class FakeHealthProvider: HealthProvider, @unchecked Sendable {
65	    private let lock = NSLock()
66	    private var batches: [HealthDomain: [HealthChangeSet]] = [:]
67	    public private(set) var authorisedDomains: Set<HealthDomain> = []
68	
69	    public init() {}
70	
71	    public func enqueue(_ set: HealthChangeSet, for domain: HealthDomain) {
72	        lock.lock(); defer { lock.unlock() }
73	        batches[domain, default: []].append(set)
74	    }
75	
76	    public func requestAuthorisation(for domains: [HealthDomain]) async throws {
77	        authorise(domains)
78	    }
79	
80	    public func changes(in domain: HealthDomain, since anchor: [UInt8]?) async throws -> HealthChangeSet {
81	        try nextChangeSet(domain, anchor)
82	    }
83	
84	    // Locks are taken only in synchronous helpers, never held across a suspension.
85	    private func authorise(_ domains: [HealthDomain]) {
86	        lock.lock(); defer { lock.unlock() }
87	        authorisedDomains.formUnion(domains)
88	    }
89	
90	    private func nextChangeSet(_ domain: HealthDomain, _ anchor: [UInt8]?) throws -> HealthChangeSet {
91	        lock.lock(); defer { lock.unlock() }
92	        guard authorisedDomains.contains(domain) else {
93	            throw HealthProviderError.authorisationDenied(domain)
94	        }
95	        guard var queue = batches[domain], !queue.isEmpty else {
96	            return HealthChangeSet(added: [], deletedExternalIDs: [], nextAnchor: anchor)
97	        }
98	        let next = queue.removeFirst()
99	        batches[domain] = queue
100	        return next
101	    }
102	}
